import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Alert, Spinner, Nav, Tab, ButtonGroup, Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { usePortfolio } from '../context/PortfolioContext';
import { Line, Pie, Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, BarElement } from 'chart.js';

// Register ChartJS components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  BarElement
);

// Helper function to safely format currency
const formatCurrency = (value) => {
  if (value === undefined || value === null) return '₹0.00';
  return '₹' + value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

// Helper function to safely format percentage
const formatPercentage = (value) => {
  if (value === undefined || value === null) return '0.00%';
  return value.toFixed(2) + '%';
};

// Helper function to safely format number
const formatNumber = (value) => {
  if (value === undefined || value === null) return '0';
  return value.toLocaleString();
};

// Helper function to get sector color
const getSectorColor = (sector) => {
  const colors = {
    'Technology': '#007bff',
    'Financial Services': '#6610f2',
    'Healthcare': '#6f42c1',
    'Consumer Discretionary': '#e83e8c',
    'Consumer Staples': '#dc3545',
    'Industrials': '#fd7e14',
    'Energy': '#ffc107',
    'Materials': '#28a745',
    'Utilities': '#20c997',
    'Real Estate': '#17a2b8',
    'Communication Services': '#6c757d',
    'Other': '#343a40'
  };

  return colors[sector] || colors['Other'];
};

const PortfolioDetail = () => {
  const navigate = useNavigate();
  const { portfolio, loading, error } = usePortfolio();
  const [activeTab, setActiveTab] = useState('overview');
  const [timeRange, setTimeRange] = useState('MAX');
  const [performanceData, setPerformanceData] = useState(null);

  useEffect(() => {
    if (portfolio && portfolio.transactions && portfolio.transactions.length > 0) {
      calculateDailyPortfolioValues();
    }
  }, [portfolio, timeRange]);

  if (loading) {
    return (
      <Container className="mt-5 text-center">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
        <p className="mt-3">Loading portfolio data...</p>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="mt-5">
        <Alert variant="danger">
          <Alert.Heading>Error Loading Portfolio</Alert.Heading>
          <p>{error}</p>
        </Alert>
      </Container>
    );
  }

  if (!portfolio) {
    return (
      <Container className="mt-5">
        <Alert variant="info">
          <Alert.Heading>No Portfolio Found</Alert.Heading>
          <p>You don't have a portfolio loaded yet. Please import your portfolio data first.</p>
        </Alert>
      </Container>
    );
  }

  // Ensure portfolio properties exist with default values
  const safePortfolio = {
    name: portfolio.name || 'My Portfolio',
    totalValue: portfolio.totalValue || 0,
    investedValue: portfolio.investedValue || 0,
    totalGainLoss: portfolio.totalGainLoss || 0,
    totalGainLossPercentage: portfolio.totalGainLossPercentage || 0,
    holdings: portfolio.holdings || [],
    transactions: portfolio.transactions || [],
    history: portfolio.history || [],
    sectorAllocation: portfolio.sectorAllocation || {},
    lastUpdated: portfolio.lastUpdated || new Date().toISOString()
  };

  // Calculate daily portfolio values by replaying transactions
  const calculateDailyPortfolioValues = () => {
    if (!safePortfolio.transactions || safePortfolio.transactions.length === 0) {
      return;
    }

    // Sort transactions by date (oldest first)
    const sortedTransactions = [...safePortfolio.transactions]
      .filter(t => t && t.date)
      .sort((a, b) => new Date(a.date) - new Date(b.date));

    if (sortedTransactions.length === 0) return;

    // Get date range
    const startDate = new Date(sortedTransactions[0].date);
    const endDate = new Date();

    // Adjust date range based on selected time period
    let filteredStartDate = new Date(startDate);

    switch (timeRange) {
      case '1D':
        filteredStartDate = new Date();
        filteredStartDate.setDate(filteredStartDate.getDate() - 1);
        break;
      case '1W':
        filteredStartDate = new Date();
        filteredStartDate.setDate(filteredStartDate.getDate() - 7);
        break;
      case '1M':
        filteredStartDate = new Date();
        filteredStartDate.setMonth(filteredStartDate.getMonth() - 1);
        break;
      case '1Y':
        filteredStartDate = new Date();
        filteredStartDate.setFullYear(filteredStartDate.getFullYear() - 1);
        break;
      case 'MAX':
      default:
        // Keep original start date
        break;
    }

    // Ensure filteredStartDate is not before the first transaction
    if (filteredStartDate < startDate) {
      filteredStartDate = new Date(startDate);
    }

    // Create a map of holdings by day
    let currentHoldings = {};
    let dailyPortfolioValues = [];
    let dailyInvestedValues = [];
    let dates = [];
    let currentDate = new Date(filteredStartDate);
    let investedValue = 0;

    // Initialize prices map (symbol -> price)
    const latestPrices = {};
    safePortfolio.holdings.forEach(holding => {
      if (holding && holding.symbol && holding.currentPrice) {
        latestPrices[holding.symbol] = holding.currentPrice;
      }
    });

    // Process all transactions up to the filtered start date to establish initial holdings
    for (const transaction of sortedTransactions) {
      const transactionDate = new Date(transaction.date);

      if (transactionDate > filteredStartDate) {
        break;
      }

      // Update holdings
      const { symbol, action, quantity, price } = transaction;

      if (!currentHoldings[symbol]) {
        currentHoldings[symbol] = { 
          quantity: 0, 
          costBasis: 0,
          symbol,
          // Store initial price for this holding
          price: latestPrices[symbol] || price
        };
      }

      if (action.toUpperCase() === 'BUY') {
        const cost = quantity * price;
        currentHoldings[symbol].quantity += quantity;
        currentHoldings[symbol].costBasis += cost;
        investedValue += cost;
      } else if (action.toUpperCase() === 'SELL') {
        const proportionalCostBasis = (quantity / currentHoldings[symbol].quantity) * currentHoldings[symbol].costBasis;
        currentHoldings[symbol].quantity -= quantity;
        currentHoldings[symbol].costBasis -= proportionalCostBasis;
        investedValue -= proportionalCostBasis;

        // Remove holding if quantity becomes 0
        if (currentHoldings[symbol].quantity <= 0) {
          currentHoldings[symbol].quantity = 0;
          currentHoldings[symbol].costBasis = 0;
        }
      }
    }

    // Calculate daily values from filteredStartDate to endDate
    while (currentDate <= endDate) {
      const dateStr = currentDate.toISOString().split('T')[0];
      dates.push(dateStr);

      // Process transactions for this day
      const dayTransactions = sortedTransactions.filter(t => {
        const tDate = new Date(t.date);
        return tDate.toISOString().split('T')[0] === dateStr;
      });

      for (const transaction of dayTransactions) {
        const { symbol, action, quantity, price } = transaction;

        if (!currentHoldings[symbol]) {
          currentHoldings[symbol] = { 
            quantity: 0, 
            costBasis: 0,
            symbol,
            price: latestPrices[symbol] || price
          };
        }

        if (action.toUpperCase() === 'BUY') {
          const cost = quantity * price;
          currentHoldings[symbol].quantity += quantity;
          currentHoldings[symbol].costBasis += cost;
          investedValue += cost;
        } else if (action.toUpperCase() === 'SELL') {
          if (currentHoldings[symbol].quantity > 0) {
            const proportionalCostBasis = (quantity / currentHoldings[symbol].quantity) * currentHoldings[symbol].costBasis;
            currentHoldings[symbol].quantity -= quantity;
            currentHoldings[symbol].costBasis -= proportionalCostBasis;
            investedValue -= proportionalCostBasis;

            // Remove holding if quantity becomes 0
            if (currentHoldings[symbol].quantity <= 0) {
              currentHoldings[symbol].quantity = 0;
              currentHoldings[symbol].costBasis = 0;
            }
          }
        }
      }

      // Calculate portfolio value for this day
      let portfolioValue = 0;
      Object.values(currentHoldings).forEach(holding => {
        if (holding.quantity > 0) {
          // Use the current price from holdings if available, otherwise use transaction price
          const currentPrice = latestPrices[holding.symbol] || holding.price;
          portfolioValue += holding.quantity * currentPrice;
        }
      });

      dailyPortfolioValues.push(portfolioValue);
      dailyInvestedValues.push(investedValue);

      // Move to next day
      currentDate.setDate(currentDate.getDate() + 1);
    }

    // Format dates for display
    const formattedDates = dates.map(date => {
      const d = new Date(date);
      return d.toLocaleDateString();
    });

    setPerformanceData({
      labels: formattedDates,
      marketValues: dailyPortfolioValues,
      investedValues: dailyInvestedValues
    });
  };

  // Prepare data for charts
  const preparePerformanceChartData = () => {
    if (!performanceData) {
      return null;
    }

    return {
      labels: performanceData.labels,
      datasets: [
        {
          label: 'Market Value',
          data: performanceData.marketValues,
          borderColor: 'rgba(75, 192, 192, 1)',
          backgroundColor: 'rgba(75, 192, 192, 0.2)',
          tension: 0.1,
        },
        {
          label: 'Invested Value',
          data: performanceData.investedValues,
          borderColor: 'rgba(153, 102, 255, 1)',
          backgroundColor: 'rgba(153, 102, 255, 0.2)',
          tension: 0.1,
        }
      ]
    };
  };

  const prepareSectorAllocationData = () => {
    if (!safePortfolio.sectorAllocation || Object.keys(safePortfolio.sectorAllocation).length === 0) {
      return null;
    }

    const sectors = Object.keys(safePortfolio.sectorAllocation);
    const values = sectors.map(sector => safePortfolio.sectorAllocation[sector] || 0);

    // Generate colors for each sector
    const backgroundColors = [
      'rgba(255, 99, 132, 0.6)',
      'rgba(54, 162, 235, 0.6)',
      'rgba(255, 206, 86, 0.6)',
      'rgba(75, 192, 192, 0.6)',
      'rgba(153, 102, 255, 0.6)',
      'rgba(255, 159, 64, 0.6)',
      'rgba(199, 199, 199, 0.6)',
      'rgba(83, 102, 255, 0.6)',
      'rgba(40, 159, 64, 0.6)',
      'rgba(210, 99, 132, 0.6)',
    ];

    return {
      labels: sectors,
      datasets: [
        {
          data: values,
          backgroundColor: backgroundColors.slice(0, sectors.length),
          borderWidth: 1,
        }
      ]
    };
  };

  const prepareHoldingsChartData = () => {
    if (!safePortfolio.holdings || safePortfolio.holdings.length === 0) {
      return null;
    }

    // Sort holdings by current value in descending order
    const sortedHoldings = [...safePortfolio.holdings]
      .filter(holding => holding && typeof holding.currentValue === 'number')
      .sort((a, b) => (b.currentValue || 0) - (a.currentValue || 0));

    // Take top 10 holdings
    const topHoldings = sortedHoldings.slice(0, 10);

    const labels = topHoldings.map(holding => holding.symbol || 'Unknown');
    const marketValues = topHoldings.map(holding => holding.currentValue || 0);
    const costValues = topHoldings.map(holding => holding.costBasis || 0);

    return {
      labels,
      datasets: [
        {
          label: 'Market Value',
          data: marketValues,
          backgroundColor: 'rgba(75, 192, 192, 0.6)',
        },
        {
          label: 'Cost Basis',
          data: costValues,
          backgroundColor: 'rgba(153, 102, 255, 0.6)',
        }
      ]
    };
  };

  const prepareHistoryChartData = () => {
    if (!safePortfolio.transactions || safePortfolio.transactions.length === 0) {
      return null;
    }

    // Create a map to count actions by type
    const actionCounts = {};

    safePortfolio.transactions.forEach(transaction => {
      if (!transaction || !transaction.action) return;

      const action = transaction.action.toUpperCase();
      if (!actionCounts[action]) {
        actionCounts[action] = 0;
      }
      actionCounts[action]++;
    });

    const labels = Object.keys(actionCounts);
    const data = Object.values(actionCounts);

    // Generate colors for each action type
    const backgroundColors = [
      'rgba(75, 192, 192, 0.6)',  // BUY - green
      'rgba(255, 99, 132, 0.6)',  // SELL - red
      'rgba(255, 206, 86, 0.6)',  // DIVIDEND - yellow
      'rgba(153, 102, 255, 0.6)', // Other
    ];

    return {
      labels,
      datasets: [
        {
          label: 'Transaction Count by Type',
          data,
          backgroundColor: backgroundColors.slice(0, labels.length),
        }
      ]
    };
  };

  const performanceChartData = preparePerformanceChartData();
  const sectorAllocationData = prepareSectorAllocationData();
  const holdingsChartData = prepareHoldingsChartData();
  const historyChartData = prepareHistoryChartData();

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
      },
      tooltip: {
        callbacks: {
          label: function(context) {
            let label = context.dataset.label || '';
            if (label) {
              label += ': ';
            }
            if (context.parsed.y !== null) {
              label += '₹' + context.parsed.y.toLocaleString('en-IN', { maximumFractionDigits: 2 });
            }
            return label;
          }
        }
      }
    },
  };

  const pieChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'right',
      },
    },
  };

  // Helper function to safely render holdings
  const getSafeHoldings = () => {
    if (!safePortfolio.holdings || !Array.isArray(safePortfolio.holdings)) {
      return [];
    }

    return safePortfolio.holdings
      .filter(holding => holding && typeof holding.currentValue === 'number')
      .sort((a, b) => (b.currentValue || 0) - (a.currentValue || 0));
  };

  // Helper function to safely render transactions
  const getSafeTransactions = () => {
    if (!safePortfolio.transactions || !Array.isArray(safePortfolio.transactions)) {
      return [];
    }

    return safePortfolio.transactions
      .filter(transaction => transaction && transaction.date)
      .sort((a, b) => new Date(b.date) - new Date(a.date));
  };

  // Helper function to safely render history
  const getSafeHistory = () => {
    if (!safePortfolio.history || !Array.isArray(safePortfolio.history)) {
      return [];
    }

    return safePortfolio.history
      .filter(entry => entry && entry.date)
      .sort((a, b) => new Date(b.date) - new Date(a.date));
  };

  // Handle time range change
  const handleTimeRangeChange = (range) => {
    setTimeRange(range);
  };

  // Calculate some performance metrics based on the performance data
  const calculatePerformanceMetrics = () => {
    if (!performanceData || performanceData.marketValues.length === 0) {
      return {
        currentValue: safePortfolio.totalValue,
        investedValue: safePortfolio.investedValue,
        absoluteReturn: safePortfolio.totalGainLoss,
        percentReturn: safePortfolio.totalGainLossPercentage
      };
    }

    const currentValue = performanceData.marketValues[performanceData.marketValues.length - 1];
    const investedValue = performanceData.investedValues[performanceData.investedValues.length - 1];
    const absoluteReturn = currentValue - investedValue;
    const percentReturn = investedValue > 0 ? (absoluteReturn / investedValue) * 100 : 0;

    return {
      currentValue,
      investedValue,
      absoluteReturn,
      percentReturn
    };
  };

  const metrics = calculatePerformanceMetrics();

  return (
    <Container className="mt-4">
      <h1 className="mb-4">{safePortfolio.name || 'Portfolio Details'}</h1>

      <Row className="mb-4">
        <Col md={4}>
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Portfolio Summary</Card.Title>
              <div className="d-flex flex-column">
                <div className="d-flex justify-content-between mb-2">
                  <span>Total Market Value:</span>
                  <span className="fw-bold">₹{safePortfolio.totalValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Total Invested:</span>
                  <span className="fw-bold">₹{safePortfolio.investedValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Total Gain/Loss:</span>
                  <span className={`fw-bold ${safePortfolio.totalGainLoss >= 0 ? 'text-success' : 'text-danger'}`}>
                    ₹{safePortfolio.totalGainLoss.toLocaleString('en-IN', { maximumFractionDigits: 2 })}
                    {' '}
                    ({safePortfolio.totalGainLossPercentage.toFixed(2)}%)
                  </span>
                </div>
                <div className="d-flex justify-content-between mb-2">
                  <span>Number of Holdings:</span>
                  <span className="fw-bold">{safePortfolio.holdings.length}</span>
                </div>
                <div className="d-flex justify-content-between">
                  <span>Last Updated:</span>
                  <span className="fw-bold">{new Date(safePortfolio.lastUpdated).toLocaleDateString()}</span>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>

        <Col md={8}>
          <Card className="h-100">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center mb-3">
                <Card.Title>Portfolio Performance</Card.Title>
                <ButtonGroup>
                  <Button 
                    variant={timeRange === '1D' ? 'primary' : 'outline-primary'} 
                    size="sm"
                    onClick={() => handleTimeRangeChange('1D')}
                  >
                    1D
                  </Button>
                  <Button 
                    variant={timeRange === '1W' ? 'primary' : 'outline-primary'} 
                    size="sm"
                    onClick={() => handleTimeRangeChange('1W')}
                  >
                    1W
                  </Button>
                  <Button 
                    variant={timeRange === '1M' ? 'primary' : 'outline-primary'} 
                    size="sm"
                    onClick={() => handleTimeRangeChange('1M')}
                  >
                    1M
                  </Button>
                  <Button 
                    variant={timeRange === '1Y' ? 'primary' : 'outline-primary'} 
                    size="sm"
                    onClick={() => handleTimeRangeChange('1Y')}
                  >
                    1Y
                  </Button>
                  <Button 
                    variant={timeRange === 'MAX' ? 'primary' : 'outline-primary'} 
                    size="sm"
                    onClick={() => handleTimeRangeChange('MAX')}
                  >
                    MAX
                  </Button>
                </ButtonGroup>
              </div>

              {/* Performance metrics for the selected time period */}
              <div className="d-flex mb-3">
                <div className="me-4">
                  <small className="text-muted">Current Value</small>
                  <div className="h5 mb-0">₹{metrics.currentValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</div>
                </div>
                <div className="me-4">
                  <small className="text-muted">Invested</small>
                  <div className="h5 mb-0">₹{metrics.investedValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</div>
                </div>
                <div>
                  <small className="text-muted">Return</small>
                  <div className={`h5 mb-0 ${metrics.absoluteReturn >= 0 ? 'text-success' : 'text-danger'}`}>
                    ₹{metrics.absoluteReturn.toLocaleString('en-IN', { maximumFractionDigits: 2 })} ({metrics.percentReturn.toFixed(2)}%)
                  </div>
                </div>
              </div>

              {performanceChartData ? (
                <div style={{ height: '250px' }}>
                  <Line data={performanceChartData} options={chartOptions} />
                </div>
              ) : (
                <Alert variant="info">
                  Not enough transaction data to display performance chart. Please add transaction data with dates to see performance over time.
                </Alert>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Nav variant="tabs" className="mb-4" activeKey={activeTab} onSelect={setActiveTab}>
        <Nav.Item>
          <Nav.Link eventKey="overview">Overview</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="holdings">Holdings</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="transactions">Transactions</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="history">History</Nav.Link>
        </Nav.Item>
      </Nav>

      <Tab.Content>
        <Tab.Pane eventKey="overview" active={activeTab === 'overview'}>
          <Row>
            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Sector Allocation</Card.Title>
                  {sectorAllocationData ? (
                    <div style={{ height: '300px' }}>
                      <Pie data={sectorAllocationData} options={pieChartOptions} />
                    </div>
                  ) : (
                    <Alert variant="info">
                      No sector allocation data available.
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Col>

            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Top Holdings</Card.Title>
                  {holdingsChartData ? (
                    <div style={{ height: '300px' }}>
                      <Bar data={holdingsChartData} options={chartOptions} />
                    </div>
                  ) : (
                    <Alert variant="info">
                      No holdings data available.
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Col>
          </Row>

          <Row>
            <Col md={12} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Top 5 Holdings (by Market Value)</Card.Title>
                  <div className="table-responsive">
                    <Table striped hover>
                      <thead>
                        <tr>
                          <th>Symbol</th>
                          <th>Company</th>
                          <th>Quantity</th>
                          <th>Avg. Cost</th>
                          <th>Current Price</th>
                          <th>Market Value</th>
                          <th>Gain/Loss</th>
                        </tr>
                      </thead>
                      <tbody>
                        {getSafeHoldings()
                          .slice(0, 5)
                          .map((holding, index) => (
                            <tr key={index}>
                              <td>{holding.symbol || 'Unknown'}</td>
                              <td>{holding.companyName || holding.symbol || 'Unknown'}</td>
                              <td>{holding.quantity || 0}</td>
                              <td>₹{(holding.avgCostPrice || 0).toFixed(2)}</td>
                              <td>₹{(holding.currentPrice || 0).toFixed(2)}</td>
                              <td>₹{(holding.currentValue || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                              <td className={(holding.unrealizedPL || 0) >= 0 ? 'text-success' : 'text-danger'}>
                                ₹{(holding.unrealizedPL || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}
                                {' '}
                                ({(holding.unrealizedPLPercent || 0).toFixed(2)}%)
                              </td>
                            </tr>
                          ))}
                      </tbody>
                    </Table>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Tab.Pane>

        <Tab.Pane eventKey="holdings" active={activeTab === 'holdings'}>
          <Card>
            <Card.Body>
              <Card.Title>All Holdings</Card.Title>
              <div className="table-responsive">
                <Table striped hover>
                  <thead>
                    <tr>
                      <th>Symbol</th>
                      <th>Company</th>
                      <th>Quantity</th>
                      <th>Avg. Cost</th>
                      <th>Current Price</th>
                      <th>Cost Basis</th>
                      <th>Market Value</th>
                      <th>Gain/Loss</th>
                      <th>Gain/Loss %</th>
                    </tr>
                  </thead>
                  <tbody>
                    {getSafeHoldings()
                      .map((holding, index) => (
                        <tr key={index}>
                          <td>{holding.symbol || 'Unknown'}</td>
                          <td>{holding.companyName || holding.symbol || 'Unknown'}</td>
                          <td>{holding.quantity || 0}</td>
                          <td>₹{(holding.avgCostPrice || 0).toFixed(2)}</td>
                          <td>₹{(holding.currentPrice || 0).toFixed(2)}</td>
                          <td>₹{(holding.costBasis || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                          <td>₹{(holding.currentValue || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                          <td className={(holding.unrealizedPL || 0) >= 0 ? 'text-success' : 'text-danger'}>
                            ₹{(holding.unrealizedPL || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}
                          </td>
                          <td className={(holding.unrealizedPLPercent || 0) >= 0 ? 'text-success' : 'text-danger'}>
                            {(holding.unrealizedPLPercent || 0).toFixed(2)}%
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Tab.Pane>

        <Tab.Pane eventKey="transactions" active={activeTab === 'transactions'}>
          <Card>
            <Card.Body>
              <Card.Title>Transaction History</Card.Title>
              <div className="table-responsive">
                <Table striped hover>
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Symbol</th>
                      <th>Company</th>
                      <th>Action</th>
                      <th>Quantity</th>
                      <th>Price</th>
                      <th>Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {getSafeTransactions()
                      .map((transaction, index) => (
                        <tr key={index}>
                          <td>{new Date(transaction.date).toLocaleDateString()}</td>
                          <td>{transaction.symbol || 'Unknown'}</td>
                          <td>{transaction.companyName || transaction.symbol || 'Unknown'}</td>
                          <td>
                            <Badge bg={(transaction.action || '').toUpperCase() === 'BUY' ? 'success' : 'danger'}>
                              {(transaction.action || 'Unknown').toUpperCase()}
                            </Badge>
                          </td>
                          <td>{transaction.quantity || 0}</td>
                          <td>₹{(transaction.price || 0).toFixed(2)}</td>
                          <td>₹{((transaction.quantity || 0) * (transaction.price || 0)).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                        </tr>
                      ))}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Tab.Pane>

        <Tab.Pane eventKey="history" active={activeTab === 'history'}>
          <Row>
            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Transaction Types</Card.Title>
                  {historyChartData ? (
                    <div style={{ height: '300px' }}>
                      <Bar data={historyChartData} options={chartOptions} />
                    </div>
                  ) : (
                    <Alert variant="info">
                      No transaction history data available.
                    </Alert>
                  )}
                </Card.Body>
              </Card>
            </Col>

            <Col md={6} className="mb-4">
              <Card>
                <Card.Body>
                  <Card.Title>Portfolio Update History</Card.Title>
                  <div className="table-responsive">
                    <Table striped hover>
                      <thead>
                        <tr>
                          <th>Date</th>
                          <th>Action</th>
                          <th>Market Value</th>
                          <th>Invested Value</th>
                        </tr>
                      </thead>
                      <tbody>
                        {getSafeHistory()
                          .map((entry, index) => (
                            <tr key={index}>
                              <td>{new Date(entry.date).toLocaleDateString()}</td>
                              <td>{entry.action || 'Update'}</td>
                              <td>₹{(entry.totalValue || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                              <td>₹{(entry.investedValue || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</td>
                            </tr>
                          ))}
                      </tbody>
                    </Table>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Tab.Pane>
      </Tab.Content>
    </Container>
  );
};

export default PortfolioDetail;
